aftmango.com/framo/assets/media/placeholder/900x1200.svg"} alt={""} width={"900"} height={"1200"} loading={"lazy"} decoding={"async"} /><span><strong>{"James Whitfield"}</strong>{"Partner, Pricing & Commercial"}</span></p><dl className={"flex gap-8"}><div className={"grid gap-0.5"}><dt className={"text-[0.9375rem] text-soft"}>{"Published"}</dt><dd className={"font-semibold tabular-nums"}><time datetime={"2026-10-12"}>{"12 Oct 2026"}</time></dd></div><div className={"grid gap-0.5"}><dt className={"text-[0.9375rem] text-soft"}>{"Reading Time"}</dt><dd className={"font-semibold tabular-nums"}>{"6 min"}</dd></div></dl><div className={"social-share ms-auto max-md:ms-0"}><span className={"social-share-label"}>{"Share"}</span><ul className={"social-list"} role={"list"}><li><button type={"button"} className={"btn btn-circle btn-copy"} data-copy-url={""} data-copy-done={"Link copied"} aria-label={"Copy the link to this article"}><i className={"ph ph-link"} aria-hidden={"true"}></i><span className={"sr-only"} data-copy-label={""} aria-live={"polite"}></span></button></li><li><a href={"#"} className={"social-link social-link--circle social-link--soft"} aria-label={"Share on LinkedIn"}><i className={"ph ph-linkedin-logo"} aria-hidden={"true"}></i></a></li><li><a href={"mailto:?subject=Pricing%20power%20in%20a%20flat%20market"} className={"social-link social-link--circle social-link--soft"} aria-label={"Share by email"}><i className={"ph ph-envelope-simple"} aria-hidden={"true"}></i></a></li></ul></div></div><figure className={"custom-article-cover mt-[clamp(2rem,1.5rem_+_2vw,3.5rem)]"} data-anim={"fade-up"}><img className={"w-full object-cover object-[50%_40%] rounded-(--custom-radius-photo)"} src={"https://draftmango.com/framo/assets/media/placeholder/1400x1050.svg"} alt={"A pricing analyst studying price curves across two monitors"} width={"1400"} height={"1050"} fetchPriority={"high"} decoding={"async"} /><figcaption className={"mt-3.5 text-[0.9375rem] text-soft"}>{"Most of the margin a price list promises is gone before the invoice is paid."}</figcaption></figure></div></section><section id={"cs-article-body"} className={"custom-section"} aria-label={"The article"}><div className={"container grid grid-cols-[minmax(0,1fr)] gap-y-12 gap-x-[clamp(3rem,1rem_+_5vw,7rem)] items-start lg:grid-cols-[minmax(0,46rem)_minmax(0,21rem)]"}><aside className={"lg:col-[2] lg:row-[1] lg:sticky lg:top-[calc(var(--navbar-h,88px)_+_2rem)]"} aria-labelledby={"cs-article-takeaways"}><div className={"custom-article-takeaways p-[clamp(1.5rem,1.25rem_+_1vw,2.25rem)] rounded-(--custom-radius-card) bg-(--custom-soft)"} data-anim={"fade-up"}><h2 id={"cs-article-takeaways"} className={"custom-article-takeaways-title flex items-center gap-2.5 text-[1.25rem] font-semibold tracking-[-0.02em]"}><i className={"ph ph-list-checks"} aria-hidden={"true"}></i>{"Key Takeaways"}</h2><ul className={"grid gap-4 mt-5 list-none"} role={"list"}><li>{"Between list price and cash, the average company we studied lets "}<strong className={"text-text"}>{"16.6%"}</strong>{" of the price slip away."}</li><li>{"The largest leak is rarely the discount on the invoice — it is the rebate nobody approved."}</li><li>{"Repricing works in waves: one category, twelve stores, four weeks, then the next."}</li><li>{"Price power is a habit run by the business, not a project run by consultants."}</li></ul></div></aside><article className={"custom-article-body"}><p className={"custom-article-first mb-6 text-[clamp(1.25rem,1.1rem_+_0.5vw,1.5rem)] leading-[1.6]"}>{"For a decade, most of the companies we work with grew their way out of trouble. Volume covered a lot of sins: a discount here, a rebate there, a freight charge quietly absorbed to keep a big customer happy. In a flat market there is nothing to cover them. The sins show up in the margin."}</p><p className={"mb-6"}>{"The usual response is a cost programme. It is the wrong place to start. On the 140 companies in our Margin Report, a one-point improvement in price was worth roughly three times a one-point cut in cost — and it took a quarter of the time to land."}</p><h2 className={"font-semibold"}>{"Where the price goes"}</h2><p className={"mb-6"}>{"Ask a commercial director what the company charges and you will get the list price. Ask the finance director what the company is paid and you will get a different number. The gap between the two is the pocket-price waterfall, and it is almost always wider than anyone in the room expects."}</p><figure className={"custom-article-exhibit my-[clamp(2.5rem,2rem_+_1.5vw,3.5rem)] pt-5"} aria-labelledby={"cs-exhibit-title"}><figcaption className={"flex flex-wrap gap-y-1 gap-x-3.5 items-baseline mb-9"}><span className={"text-[0.9375rem] font-semibold text-primary-ink"}>{"Exhibit 1"}</span><span id={"cs-exhibit-title"} className={"font-heading text-[1.25rem] font-semibold tracking-[-0.02em] text-text"}>{"Where £100 of list price goes"}</span></figcaption><ol className={"custom-article-bars grid grid-cols-6 gap-y-0 gap-x-[clamp(0.375rem,0.1rem_+_1vw,1.25rem)] list-none max-[30rem]:gap-x-1"} role={"list"}><li className={"grid grid-rows-[var(--custom-plot)_auto]"} style={{"--b": "0", "--h": "100"}}><span className={"custom-article-bar"} aria-hidden={"true"}></span><span className={"custom-article-bar-value"}>{"100"}</span><span className={"custom-article-bar-label"}>{"List price"}</span></li><li className={"is-step grid grid-rows-[var(--custom-plot)_auto]"} style={{"--b": "63.2", "--h": "36.8"}}><span className={"custom-article-bar"} aria-hidden={"true"}></span><span className={"custom-article-bar-value"}>{"−9.2"}</span><span className={"custom-article-bar-label"}>{"On-invoice discounts"}</span></li><li className={"is-step is-key grid grid-rows-[var(--custom-plot)_auto]"} style={{"--b": "46.8", "--h": "16.4"}}><span className={"custom-article-bar"} aria-hidden={"true"}></span><span className={"custom-article-bar-value"}>{"−4.1"}</span><span className={"custom-article-bar-label"}>{"Off-invoice rebates"}</span></li><li className={"is-step grid grid-rows-[var(--custom-plot)_auto]"} style={{"--b": "41.6", "--h": "5.2"}}><span className={"custom-article-bar"} aria-hidden={"true"}></span><span className={"custom-article-bar-value"}>{"−1.3"}</span><span className={"custom-article-bar-label"}>{"Payment terms"}</span></li><li className={"is-step grid grid-rows-[var(--custom-plot)_auto]"} style={{"--b": "33.6", "--h": "8"}}><span className={"custom-article-bar"} aria-hidden={"true"}></span><span className={"custom-article-bar-value"}>{"−2.0"}</span><span className={"custom-article-bar-label"}>{"Freight & service"}</span></li><li className={"is-end grid grid-rows-[var(--custom-plot)_auto]"} style={{"--b": "0", "--h": "33.6"}}><span className={"custom-article-bar"} aria-hidden={"true"}></span><span className={"custom-article-bar-value"}>{"83.4"}</span><span className={"custom-article-bar-label"}>{"Pocket price"}</span></li></ol><p className={"mt-6 text-[0.9375rem] leading-[1.5] text-soft"}>{"Average of 140 mid-market companies, 2025; the axis starts at 75. Source: Framo Partners, The Margin Report 2026."}</p></figure><p className={"mb-6"}>{"The striking line is not the discount on the invoice; everyone knows about that. It is the "}<mark className={"custom-article-mark"}>{"4.1 points of off-invoice rebates"}</mark>{": volume bonuses, marketing funds and year-end payments agreed by account managers, paid by finance, and owned by nobody."}</p><h2 className={"font-semibold"}>{"Why the lever stays unpulled"}</h2><p className={"mb-6"}>{"Three things keep companies from using price. They fear losing volume they cannot afford to lose. They price by rule of thumb — cost plus a margin set years ago — across tens of thousands of lines. And nobody owns the whole waterfall: sales owns the list, finance owns the rebates, logistics owns the freight."}</p><blockquote className={"custom-article-quote my-[clamp(2.5rem,2rem_+_1.5vw,3.5rem)] py-8"}><p className={"font-heading text-[clamp(1.75rem,1.3rem_+_1.6vw,2.75rem)] font-normal leading-[1.12] tracking-[-0.04em] text-balance text-text"}>{"You don't need pricing power to raise prices. "}<strong className={"font-semibold text-primary-ink"}>{"You need it to stop giving them away."}</strong></p></blockquote><p className={"mb-6"}>{"That is the good news in a flat market. Most of the margin we recover for clients does not come from charging customers more. It comes from charging them what was already agreed, and from asking for something back every time a discount is given."}</p><h2 className={"font-semibold"}>{"Four moves that work in a flat year"}</h2><p className={"mb-6"}>{"At Halden Retail we repriced 40,000 lines in four waves and added 310 basis points of EBITDA margin in fourteen months. The method travels well beyond grocery:"}</p><ol className={"custom-article-list grid gap-4 mb-7 list-none"}><li className={"relative ps-12"}><strong className={"text-text"}>{"Draw the waterfall"}</strong>{" for every category in three weeks, from invoice data you already hold."}</li><li className={"relative ps-12"}><strong className={"text-text"}>{"Close the leaks first"}</strong>{" — unapproved rebates and unpaid terms — before touching a single list price."}</li><li className={"relative ps-12"}><strong className={"text-text"}>{"Reprice in waves"}</strong>{", testing each one in a small set of stores or accounts before rolling it out."}</li><li className={"relative ps-12"}><strong className={"text-text"}>{"Give one person the waterfall"}</strong>{", with a monthly review the leadership team actually attends."}</li></ol><p className={"mb-6"}>{"None of this needs a new system. It needs a fact base, a few hard conversations with key accounts, and the patience to do it category by category. The companies that grew margin through 2025 were 3.1 times more likely to have repriced in the twelve months before."}</p><p className={"custom-article-sign font-semibold mb-6"}>{"— James Whitfield, London"